edits.before:
document.getElementById('items').addEventListener('click', event => {
    const button = event.target.closest('button');
    if (!button) return;
    button.closest('li').remove();
    const left = document.querySelectorAll('#items li').length;
    document.getElementById('count').textContent = left + (left === 1 ? ' item' : ' items');
  }

